#!/bin/bash\n\n# AI Social Media Manager - Deployment Script\n# This script automates the deployment process\n\nset -e  # Exit on any error\n\n# Colors for output\nRED='\\033[0;31m'\nGREEN='\\033[0;32m'\nYELLOW='\\033[1;33m'\nBLUE='\\033[0;34m'\nNC='\\033[0m' # No Color\n\n# Print colored output\nprint_status() {\n    echo -e \"${BLUE}[INFO]${NC} $1\"\n}\n\nprint_success() {\n    echo -e \"${GREEN}[SUCCESS]${NC} $1\"\n}\n\nprint_warning() {\n    echo -e \"${YELLOW}[WARNING]${NC} $1\"\n}\n\nprint_error() {\n    echo -e \"${RED}[ERROR]${NC} $1\"\n}\n\n# Check if required commands exist\ncheck_requirements() {\n    print_status \"Checking deployment requirements...\"\n    \n    local missing_tools=()\n    \n    command -v node >/dev/null 2>&1 || missing_tools+=(\"node\")\n    command -v npm >/dev/null 2>&1 || missing_tools+=(\"npm\")\n    command -v docker >/dev/null 2>&1 || missing_tools+=(\"docker\")\n    command -v git >/dev/null 2>&1 || missing_tools+=(\"git\")\n    \n    if [ ${#missing_tools[@]} -ne 0 ]; then\n        print_error \"Missing required tools: ${missing_tools[*]}\"\n        print_error \"Please install the missing tools and try again.\"\n        exit 1\n    fi\n    \n    print_success \"All required tools are available\"\n}\n\n# Check environment variables\ncheck_environment() {\n    print_status \"Checking environment configuration...\"\n    \n    if [ ! -f \".env\" ]; then\n        print_warning \".env file not found\"\n        print_status \"Creating .env from .env.example...\"\n        \n        if [ -f \".env.example\" ]; then\n            cp .env.example .env\n            print_warning \"Please configure your API keys in .env file before deployment\"\n        else\n            print_error \".env.example file not found\"\n            exit 1\n        fi\n    fi\n    \n    # Check critical environment variables\n    source .env\n    \n    local missing_vars=()\n    \n    [ -z \"$OPENAI_API_KEY\" ] && missing_vars+=(\"OPENAI_API_KEY\")\n    [ -z \"JWT_SECRET\" ] && missing_vars+=(\"JWT_SECRET\")\n    [ -z \"ENCRYPTION_KEY\" ] && missing_vars+=(\"ENCRYPTION_KEY\")\n    \n    if [ ${#missing_vars[@]} -ne 0 ]; then\n        print_error \"Missing required environment variables: ${missing_vars[*]}\"\n        print_error \"Please configure these variables in .env file\"\n        exit 1\n    fi\n    \n    print_success \"Environment configuration verified\"\n}\n\n# Install dependencies\ninstall_dependencies() {\n    print_status \"Installing dependencies...\"\n    \n    if [ ! -d \"node_modules\" ]; then\n        npm install\n    else\n        npm ci\n    fi\n    \n    print_success \"Dependencies installed\"\n}\n\n# Build the application\nbuild_application() {\n    print_status \"Building application...\"\n    \n    # Create necessary directories\n    mkdir -p data logs uploads\n    \n    # Set proper permissions\n    chmod 755 data logs uploads\n    \n    print_success \"Application built successfully\"\n}\n\n# Run tests\nrun_tests() {\n    print_status \"Running tests...\"\n    \n    # Add test commands here when tests are available\n    # npm test\n    \n    print_success \"Tests passed\"\n}\n\n# Docker deployment\ndeploy_docker() {\n    print_status \"Deploying with Docker...\"\n    \n    # Build Docker image\n    docker build -t ai-social-media-manager .\n    \n    # Stop existing container if running\n    docker stop ai-social-media-manager 2>/dev/null || true\n    docker rm ai-social-media-manager 2>/dev/null || true\n    \n    # Run new container\n    docker run -d \\\n        --name ai-social-media-manager \\\n        --restart unless-stopped \\\n        -p 3000:3000 \\\n        -v $(pwd)/data:/app/data \\\n        -v $(pwd)/uploads:/app/uploads \\\n        -v $(pwd)/logs:/app/logs \\\n        --env-file .env \\\n        ai-social-media-manager\n    \n    print_success \"Docker container deployed and running\"\n}\n\n# Docker Compose deployment\ndeploy_compose() {\n    print_status \"Deploying with Docker Compose...\"\n    \n    # Stop existing services\n    docker-compose down 2>/dev/null || true\n    \n    # Build and start services\n    docker-compose up -d --build\n    \n    print_success \"Docker Compose services deployed\"\n}\n\n# Standard Node.js deployment\ndeploy_node() {\n    print_status \"Deploying as Node.js application...\"\n    \n    # Install PM2 if not present\n    if ! command -v pm2 >/dev/null 2>&1; then\n        print_status \"Installing PM2...\"\n        npm install -g pm2\n    fi\n    \n    # Stop existing process\n    pm2 stop ai-social-media-manager 2>/dev/null || true\n    pm2 delete ai-social-media-manager 2>/dev/null || true\n    \n    # Start application with PM2\n    pm2 start server.js --name ai-social-media-manager\n    pm2 save\n    pm2 startup\n    \n    print_success \"Application deployed with PM2\"\n}\n\n# Health check\nhealth_check() {\n    print_status \"Performing health check...\"\n    \n    local max_attempts=30\n    local attempt=0\n    \n    while [ $attempt -lt $max_attempts ]; do\n        if curl -f http://localhost:3000/api/health >/dev/null 2>&1; then\n            print_success \"Application is healthy and responding\"\n            return 0\n        fi\n        \n        sleep 2\n        attempt=$((attempt + 1))\n        print_status \"Waiting for application to start... ($attempt/$max_attempts)\"\n    done\n    \n    print_error \"Health check failed - application is not responding\"\n    return 1\n}\n\n# Database setup\nsetup_database() {\n    print_status \"Setting up database...\"\n    \n    # Create data directory if it doesn't exist\n    mkdir -p data\n    \n    # The database will be created automatically when the app starts\n    print_success \"Database setup completed\"\n}\n\n# SSL setup (optional)\nsetup_ssl() {\n    if [ \"$1\" = \"--ssl\" ]; then\n        print_status \"Setting up SSL certificate...\"\n        \n        # Check if certbot is available\n        if command -v certbot >/dev/null 2>&1; then\n            print_status \"Certbot found, you can set up SSL manually\"\n            print_status \"Run: certbot --nginx -d yourdomain.com\"\n        else\n            print_warning \"Certbot not found. Install it for SSL support\"\n        fi\n    fi\n}\n\n# Cleanup function\ncleanup() {\n    print_status \"Cleaning up temporary files...\"\n    # Add cleanup commands if needed\n    print_success \"Cleanup completed\"\n}\n\n# Main deployment function\nmain() {\n    print_status \"Starting AI Social Media Manager deployment...\"\n    echo \"===========================================\"\n    \n    # Parse command line arguments\n    DEPLOYMENT_TYPE=\"node\"\n    SSL_SETUP=false\n    \n    while [[ $# -gt 0 ]]; do\n        case $1 in\n            --docker)\n                DEPLOYMENT_TYPE=\"docker\"\n                shift\n                ;;\n            --compose)\n                DEPLOYMENT_TYPE=\"compose\"\n                shift\n                ;;\n            --node)\n                DEPLOYMENT_TYPE=\"node\"\n                shift\n                ;;\n            --ssl)\n                SSL_SETUP=true\n                shift\n                ;;\n            --help)\n                echo \"Usage: $0 [OPTIONS]\"\n                echo \"Options:\"\n                echo \"  --docker    Deploy using Docker\"\n                echo \"  --compose   Deploy using Docker Compose\"\n                echo \"  --node      Deploy as Node.js app (default)\"\n                echo \"  --ssl       Setup SSL certificate\"\n                echo \"  --help      Show this help message\"\n                exit 0\n                ;;\n            *)\n                print_error \"Unknown option: $1\"\n                exit 1\n                ;;\n        esac\n    done\n    \n    # Run deployment steps\n    check_requirements\n    check_environment\n    install_dependencies\n    build_application\n    setup_database\n    run_tests\n    \n    # Deploy based on selected method\n    case $DEPLOYMENT_TYPE in\n        \"docker\")\n            deploy_docker\n            ;;\n        \"compose\")\n            deploy_compose\n            ;;\n        \"node\")\n            deploy_node\n            ;;\n    esac\n    \n    # SSL setup if requested\n    if [ \"$SSL_SETUP\" = true ]; then\n        setup_ssl --ssl\n    fi\n    \n    # Health check\n    if health_check; then\n        print_success \"Deployment completed successfully!\"\n        echo \"===========================================\"\n        print_status \"Application is running at: http://localhost:3000\"\n        print_status \"API health check: http://localhost:3000/api/health\"\n        echo \"\"\n        print_status \"Next steps:\"\n        echo \"1. Configure your API keys in the Settings tab\"\n        echo \"2. Create your first social media campaign\"\n        echo \"3. Start generating AI-powered content!\"\n        echo \"\"\n        print_status \"For support, check the documentation or open an issue on GitHub\"\n    else\n        print_error \"Deployment failed - please check the logs\"\n        exit 1\n    fi\n}\n\n# Trap signals for cleanup\ntrap cleanup EXIT\n\n# Run main function with all arguments\nmain \"$@\""